    /// The Swift export's theme lines, as pasted; the export applies the result with `.registryTheme(theme)`.
    static func swiftTheme(_ id: String) -> RegistryTheme? {
        switch id {
        case "accent-blue":
            let theme = RegistryTheme(
                accent: .blue,
                onAccent: .white,
                surface: .primary.opacity(0.055),
                border: .primary.opacity(0.080),
                disabledOpacity: 0.500,
                metrics: RegistryMetrics(
                    compactSpacing: 8,
                    standardSpacing: 16,
                    sectionSpacing: 24,
                    controlHorizontalPadding: 12,
                    borderWidth: 1,
                    emphasizedBorderWidth: 2,
                    compactRadius: 6,
                    controlRadius: 8,
                    cardRadius: 16
                )
            )
            return theme
        case "accent-brown":
            let theme = RegistryTheme(
                accent: .brown,
